import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        String[] people = {"Ana", "Ben", "Cy", "Dee"};
        List<List<Integer>> friends = new ArrayList<>();
        for (int i = 0; i < people.length; i++) {
            friends.add(new ArrayList<>());
        }
        addFriendship(friends, 0, 1); // Ana - Ben
        addFriendship(friends, 0, 2); // Ana - Cy
        addFriendship(friends, 2, 3); // Cy - Dee

        for (int i = 0; i < people.length; i++) {
            String names = "";
            for (int f : friends.get(i)) {
                names += people[f] + " ";
            }
            System.out.println(people[i] + ": " + names);
        }
    }

    static void addFriendship(List<List<Integer>> friends, int a, int b) {
        friends.get(a).add(b);
        friends.get(b).add(a);
    }
}
